:root{
--bg:#F3F6FA; --board:#FFFFFF; --slot:#EEF3F9; --slot2:#E0E9F3; --cell:#E7EEF7;
--line:#DCE5EF; --line2:#C5D3E2; --shadow:#D7E1EC;
--ink:#1F2733; --ink2:#57616F; --cream:#27384B; --btn-ink:#17202B;
--pink:#F2678F; --pink-t:#C22C5F; --pink-d:#C74B77; --pink-soft:#FFE6EE;
--mint:#2FC3AE; --mint-t:#0A7A6E; --mint-d:#1B8F80; --mint-soft:#DBF5F0;
--gold:#F5BE4C; --gold-t:#8A5E09; --gold-d:#C08A12; --gold-soft:#FFF2D6;
--lav:#6A5AD6; --lav-t:#5546C0; --lav-soft:#E8E5FF;
--cellfilter:grayscale(1) opacity(.3);
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){
--bg:#10151C; --board:#1B2330; --slot:#161D28; --slot2:#101620; --cell:#0F141C;
--line:#2B3644; --line2:#3A4859; --shadow:#0A0E14;
--ink:#EDF2F8; --ink2:#9BA8B8; --cream:#FFDFA8; --btn-ink:#111820;
--pink:#FF89AB; --pink-t:#FF89AB; --pink-d:#C74B77; --pink-soft:#38222B;
--mint:#4FD8C0; --mint-t:#4FD8C0; --mint-d:#1B8F80; --mint-soft:#12302C;
--gold:#F5B23A; --gold-t:#F5B23A; --gold-d:#A9740E; --gold-soft:#33280F;
--lav:#A79BFF; --lav-t:#A79BFF; --lav-soft:#232A46;
--cellfilter:grayscale(1) brightness(.42);
}}
:root[data-theme="dark"]{
--bg:#10151C; --board:#1B2330; --slot:#161D28; --slot2:#101620; --cell:#0F141C;
--line:#2B3644; --line2:#3A4859; --shadow:#0A0E14;
--ink:#EDF2F8; --ink2:#9BA8B8; --cream:#FFDFA8; --btn-ink:#111820;
--pink:#FF89AB; --pink-t:#FF89AB; --pink-d:#C74B77; --pink-soft:#38222B;
--mint:#4FD8C0; --mint-t:#4FD8C0; --mint-d:#1B8F80; --mint-soft:#12302C;
--gold:#F5B23A; --gold-t:#F5B23A; --gold-d:#A9740E; --gold-soft:#33280F;
--lav:#A79BFF; --lav-t:#A79BFF; --lav-soft:#232A46;
--cellfilter:grayscale(1) brightness(.42);
}
*{box-sizing:border-box}
html,body{margin:0}
body{background:var(--bg);color:var(--ink);font-family:"Pretendard Variable","Apple SD Gothic Neo",sans-serif;font-size:16px;line-height:1.5}
.wrap{max-width:900px;margin:0 auto;padding:20px 14px 48px}
.num{font-family:"JetBrains Mono",monospace;letter-spacing:-.02em}
h1{font-size:clamp(22px,4.4vw,32px);margin:0 0 2px;color:var(--cream)}
h1 .sub{display:block;font-family:"JetBrains Mono",monospace;font-size:10px;color:var(--pink-t);margin-bottom:8px;letter-spacing:.06em}
.lead{color:var(--ink2);font-size:14px;margin:0 0 18px;max-width:66ch}
.board{background:var(--board);border:3px solid var(--line2);border-radius:6px;padding:16px;box-shadow:0 6px 0 var(--shadow);overflow:hidden}
.top{display:grid;grid-template-columns:190px 1fr;gap:18px}
@media(max-width:640px){.top{grid-template-columns:1fr}}
.stage{background:var(--slot);border:2px solid var(--line2);border-radius:4px;padding:14px;text-align:center}
canvas{image-rendering:pixelated;image-rendering:crisp-edges;display:block}
#hero{width:132px;height:176px;margin:0 auto;object-fit:cover;display:block;border-radius:3px;background:var(--slot2)}
#hero.land{object-fit:contain}
img.pix{image-rendering:pixelated;image-rendering:crisp-edges}
.stage .tag{font-family:"JetBrains Mono",monospace;font-size:9px;margin-top:10px;color:var(--gold-t)}
.stage .tag2{font-size:14px;color:var(--ink);margin-top:4px;min-height:21px}
.stage.pop{animation:pop .22s steps(3)}
@keyframes pop{0%{transform:translateY(0)}40%{transform:translateY(-8px) rotate(-2deg)}100%{transform:translateY(0)}}
@media (prefers-reduced-motion:reduce){.stage.pop{animation:none}}
.btns{display:flex;flex-wrap:wrap;gap:8px}
button{font-family:"Pretendard Variable",sans-serif;font-size:15px;color:var(--ink);background:var(--gold-soft);border:0;border-bottom:4px solid var(--gold-d);border-radius:3px;padding:9px 14px;cursor:pointer}
button:active{transform:translateY(2px);border-bottom-width:2px}
button.p{background:var(--pink);color:var(--btn-ink);border-bottom-color:var(--pink-d)}
button.m{background:var(--mint);color:var(--btn-ink);border-bottom-color:var(--mint-d)}
button:disabled{opacity:.35;cursor:default;transform:none}
button:focus-visible{outline:3px solid var(--lav);outline-offset:2px}
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:14px}
@media(max-width:640px){.stats{grid-template-columns:1fr 1fr}}
.st{background:var(--slot);border:1px solid var(--line);border-radius:4px;padding:10px}
.st b{display:block;font-family:"JetBrains Mono",monospace;font-size:clamp(11px,3vw,14px);color:var(--ink);margin-bottom:5px;overflow-wrap:anywhere}
.st span{font-size:13px;color:var(--ink2)}
.bar{height:14px;background:var(--slot2);border:1px solid var(--line);border-radius:3px;margin-top:14px;overflow:hidden}
.bar i{display:block;height:100%;background:var(--pink);width:0}
.sets{margin-top:16px;display:grid;gap:10px}
.set{background:var(--slot);border:1px solid var(--line);border-radius:4px;padding:8px 10px 10px}
.shead{display:flex;align-items:center;gap:8px;font-size:14px;margin-bottom:7px}
.shead .chip{width:11px;height:11px;display:inline-block}
.shead .pr{margin-left:auto;font-family:"JetBrains Mono",monospace;font-size:9px;color:var(--ink2)}
.shead .vs{font-size:12px;color:var(--ink2)}
.row{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}
.row.wide{grid-template-columns:repeat(2,1fr);margin-top:10px}
.cell.land{aspect-ratio:4/3}
@media(max-width:640px){.row.wide{grid-template-columns:1fr 1fr}}
.set.sp .row{grid-template-columns:repeat(4,1fr)}
.cell{position:relative;background:var(--cell);border:2px solid var(--line2);border-radius:3px;aspect-ratio:3/4;overflow:visible}
.cell img{width:100%;height:100%;object-fit:cover;display:block;filter:var(--cellfilter)}
.cell.own{border-color:var(--pink)}
.cell.own img{filter:none}
.cell.flash{border-color:var(--gold);box-shadow:0 0 0 3px var(--gold)}
.cell .d{position:absolute;right:-3px;bottom:-3px;background:var(--gold);color:var(--btn-ink);font-family:"JetBrains Mono",monospace;font-size:8px;padding:2px 3px}
.gitem{display:flex;flex-direction:column}
.gitem .v{margin-top:5px;background:var(--slot2);border:1px solid var(--line);border-radius:3px;padding:3px 5px;font-size:11px;line-height:1.3;color:var(--ink2);text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.gitem.own .v{background:var(--pink-soft);border-color:var(--pink-d);color:var(--ink)}
.set{padding-bottom:10px}
.result{margin-top:14px;background:var(--gold-soft);border:2px solid var(--gold-d);border-radius:5px;padding:14px}
.result .r1{font-family:"Pretendard Variable",sans-serif;font-size:clamp(16px,4.6vw,22px);color:var(--gold-t);margin-bottom:8px;display:flex;align-items:baseline;flex-wrap:wrap;gap:4px 10px}
.result .r1 .fig{font-family:"JetBrains Mono",monospace;font-size:.92em;overflow-wrap:anywhere}
.result .r1 .tagx{font-size:.8em;display:inline-block;padding:3px 11px;border:2px solid;line-height:1.35;white-space:nowrap;position:relative}
.result .r1 .tagx.mix{color:var(--btn-ink);background:var(--mint);border-color:var(--mint-d);box-shadow:0 3px 0 var(--mint-d)}
.result .r1 .tagx.pure{
color:#3c2406;border-color:var(--gold-d);
background:linear-gradient(100deg,#ffeaae 0%,#f6b93c 26%,#fff8e0 44%,#f6b93c 62%,#ffd977 100%);
background-size:280% 100%;
text-shadow:0 1px 0 rgba(255,255,255,.65);
animation:sheen 2.4s linear infinite, glowpulse 1.5s ease-in-out infinite;
}
.result .r1 .tagx.pure::before{content:"\2726";margin-right:6px;display:inline-block;animation:tw 1.1s steps(2,end) infinite}
.result .r1 .tagx.pure::after{content:"\2726";margin-left:6px;display:inline-block;animation:tw 1.1s steps(2,end) .55s infinite}
@keyframes sheen{0%{background-position:0% 50%}100%{background-position:280% 50%}}
@keyframes glowpulse{0%,100%{box-shadow:0 3px 0 #9c7016,0 0 8px rgba(246,185,60,.45)}50%{box-shadow:0 3px 0 #9c7016,0 0 22px rgba(255,222,130,.95)}}
@keyframes tw{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.35;transform:scale(.8)}}
.result.pure{border-color:var(--gold-d);box-shadow:0 0 20px rgba(246,185,60,.35)}
@media (prefers-reduced-motion:reduce){
.result .r1 .tagx.pure,.result .r1 .tagx.pure::before,.result .r1 .tagx.pure::after{animation:none}
}
.result .r2{font-size:14px}
.result .r3{font-size:13px;color:var(--ink2);margin-top:6px}
.rps{margin-top:12px;background:var(--mint-soft);border:2px solid var(--mint-d);border-radius:4px;padding:12px}
.rps .q{font-size:14px;margin-bottom:8px}
.rps .hands{display:flex;gap:8px;flex-wrap:wrap}
.rps .hands button{font-size:15px;padding:10px 16px}
.rps .out{margin-top:10px;font-size:14px;min-height:22px}
.rps .out b{color:var(--ink)}
.rps .out .w{color:var(--mint-t)}
.rps .out .l{color:var(--pink-t)}
.rps .sc{font-size:12px;color:var(--ink2);margin-top:6px}
#toasts{position:fixed;left:50%;top:16px;transform:translateX(-50%);z-index:110;
display:flex;flex-direction:column;gap:8px;align-items:center;pointer-events:none;width:max-content;max-width:94vw}
.toast{background:var(--board);border:2px solid var(--gold-d);border-radius:8px;padding:10px 16px;
box-shadow:0 8px 26px rgba(0,0,0,.28);text-align:center;
animation:toastIn .32s cubic-bezier(.2,1.2,.4,1),toastOut .4s ease-in 4.6s forwards}
.toast b{display:block;font-family:"Pretendard Variable",sans-serif;font-size:17px;color:var(--gold-t);margin-bottom:2px}
.toast span{font-size:13px;color:var(--ink2)}
@keyframes toastIn{0%{opacity:0;transform:translateY(-14px) scale(.94)}100%{opacity:1;transform:none}}
@keyframes toastOut{100%{opacity:0;transform:translateY(-10px)}}
.badges{display:flex;flex-wrap:wrap;gap:6px;width:100%;margin-top:4px}
.badges .bd{display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:4px 9px;border-radius:999px;
background:var(--gold-soft);border:1px solid var(--gold-d);color:var(--gold-t)}
.badges .bd::before{content:"\2726";font-size:10px}
.badges .bd.hid{background:var(--slot2);border-color:var(--line);color:var(--ink2)}
#fxlayer .cardrain{position:absolute;top:-90px;width:46px;border-radius:4px;box-shadow:0 6px 14px rgba(0,0,0,.3);
animation:cardfall var(--dur,3.2s) linear forwards}
@keyframes cardfall{0%{transform:translateY(0) rotate(0deg)}100%{transform:translateY(112vh) rotate(var(--rot,540deg));opacity:.25}}
.ctile.pv{--lv:5;--tier:#f6b93c;--tier2:#fff6d5;--tierd:#b8860b}
.ctile.pv .lvb{display:inline-flex}
.ctile.pv .ring i{--rd:1.7s}
.ctile.pv .pic img{filter:none}
#fxlayer{position:fixed;inset:0;pointer-events:none;z-index:90;overflow:hidden}
#fxlayer .fw{position:absolute;width:0;height:0}
#fxlayer .fw i{position:absolute;left:0;top:0;width:7px;height:7px;margin:-3px 0 0 -3px;border-radius:50%;
background:var(--pc,#f6b93c);box-shadow:0 0 10px var(--pc,#f6b93c);
animation:fwgo var(--dur,1.1s) cubic-bezier(.15,.7,.3,1) forwards}
@keyframes fwgo{0%{transform:translate(0,0) scale(1);opacity:1}
72%{opacity:1}100%{transform:translate(var(--tx),var(--ty)) scale(.3);opacity:0}}
#fxlayer .cfi{position:absolute;top:-18px;width:8px;height:14px;background:var(--pc,#f6b93c);border-radius:1px;
animation:cfall var(--dur,3s) linear forwards}
@keyframes cfall{0%{transform:translateY(0) rotate(0deg);opacity:1}
100%{transform:translateY(106vh) rotate(760deg);opacity:.15}}
#fxlayer .glint{--gc:#ffe9a8}
#totop{position:fixed;right:18px;bottom:18px;width:46px;height:46px;border-radius:50%;
background:color-mix(in srgb, var(--board) 72%, transparent);
border:1px solid var(--line2);border-bottom:1px solid var(--line2);
color:var(--ink);cursor:pointer;display:flex;align-items:center;justify-content:center;
box-shadow:0 2px 10px rgba(0,0,0,.18);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);
opacity:0;visibility:hidden;transform:translateY(8px);transition:opacity .18s ease,transform .18s ease,visibility .18s;z-index:50;padding:0}
#totop.show{opacity:.85;visibility:visible;transform:translateY(0)}
#totop:hover{opacity:1}
#totop:active{transform:translateY(2px)}
#totop svg{width:20px;height:20px;display:block}
@media (prefers-reduced-motion:reduce){#totop{transition:none}}
.credit{display:inline-flex;align-items:center;flex-wrap:wrap;gap:0 6px;margin:0 0 14px;padding:6px 11px;
border:1px solid var(--line);border-left:3px solid var(--gold-d);border-radius:3px;background:var(--slot);
font-family:"JetBrains Mono",monospace;font-size:8px;line-height:1.8;letter-spacing:.04em;color:var(--ink2)}
.credit b{font-family:"Pretendard Variable",sans-serif;font-size:13px;font-weight:400;letter-spacing:0;color:var(--gold-t)}
@media(max-width:640px){.credit{font-size:7px}.credit b{font-size:12px}}
.tabs{display:flex;gap:8px;margin:0 0 14px}
.tabs button{font-size:15px;padding:9px 18px;background:var(--slot);color:var(--ink2);border:1px solid var(--line);border-bottom:4px solid var(--line2);border-radius:4px}
.tabs button.on{background:var(--pink);color:var(--btn-ink);border-color:var(--pink-d);border-bottom-color:var(--pink-d)}
.chead2{display:flex;flex-wrap:wrap;gap:12px 22px;align-items:flex-end;background:var(--slot);border:1px solid var(--line);border-radius:4px;padding:14px;margin-bottom:14px}
.chead2 .m{min-width:120px}
.chead2 .m b{display:block;font-family:"JetBrains Mono",monospace;font-size:clamp(14px,4.2vw,20px);color:var(--ink);margin-bottom:6px;overflow-wrap:anywhere}
.chead2 .m span{font-size:13px;color:var(--ink2)}
.chead2 .sp{margin-left:auto;display:flex;gap:8px}
.mask{position:fixed;inset:0;background:rgba(16,21,28,.55);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);
display:flex;align-items:center;justify-content:center;padding:16px;z-index:100}
.mask[hidden]{display:none}
.modal{background:var(--board);border:2px solid var(--line2);border-radius:8px;box-shadow:0 10px 30px rgba(0,0,0,.28);
width:100%;max-width:720px;max-height:86vh;display:flex;flex-direction:column;overflow:hidden}
.modal .mh{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line)}
.modal .mh b{font-size:16px;color:var(--ink)}
.modal .mh span{font-size:13px;color:var(--ink2)}
.modal .mh button{margin-left:auto;padding:6px 12px;font-size:14px}
.modal .mb{padding:14px;overflow:auto}
.mgrid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}
@media(max-width:640px){.mgrid{grid-template-columns:repeat(3,1fr)}}
.mcard{background:var(--slot);border:1px solid var(--line);border-radius:4px;padding:5px;cursor:pointer;text-align:left}
.mcard:hover{border-color:var(--pink-d);background:var(--pink-soft)}
.mcard img{width:100%;aspect-ratio:3/4;object-fit:cover;display:block;border-radius:3px;border:1px solid var(--line2)}
.mcard.land img{aspect-ratio:4/3}
.mcard .cn{font-size:11px;color:var(--ink2);margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mcard .cq{font-family:"JetBrains Mono",monospace;font-size:9px;color:var(--ink);margin-top:3px}
.mqty{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:14px;padding:10px 12px;
background:var(--slot);border:1px solid var(--line);border-radius:4px}
.mqty .lb{font-size:13px;color:var(--ink2);margin-right:2px}
.mqty .st{display:flex;align-items:center;gap:8px}
.mqty .st button{width:38px;padding:6px 0;font-size:17px;line-height:1;text-align:center;border-bottom-width:3px}
.mqty .st .n{min-width:52px;text-align:center;font-family:"JetBrains Mono",monospace;font-size:14px;color:var(--ink)}
.mqty .ps{display:flex;gap:6px;margin-left:auto}
.mqty .ps button{padding:6px 10px;font-size:13px;border-bottom-width:3px}
.msrc{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
@media(max-width:640px){.msrc{grid-template-columns:1fr}}
.msrc button{padding:14px;font-size:15px;text-align:left}
.msrc button small{display:block;font-size:12px;opacity:.75;margin-top:3px}
.clog{margin-top:14px;background:var(--slot);border:1px solid var(--line);border-radius:4px;padding:12px}
.clog h4{margin:0 0 8px;font-size:14px;color:var(--ink)}
.clog .list{max-height:220px;overflow:auto;font-size:13px;color:var(--ink2)}
.clog .list div{padding:3px 0;border-bottom:1px solid var(--line)}
.clog .list div:last-child{border-bottom:0}
.clog .list b{color:var(--ink);font-weight:400}
.clog .list .tg{display:inline-block;min-width:62px;font-size:11px;color:var(--ink2)}
.clog .em{color:var(--ink2);font-size:13px}
.cledger{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:14px}
@media(max-width:640px){.cledger{grid-template-columns:1fr}}
.cledger .lg{background:var(--slot);border:1px solid var(--line);border-radius:4px;padding:10px 12px}
.cledger .lg .t{font-size:13px;color:var(--ink2);margin-bottom:7px}
.cledger .lg .t input{width:74px;font-family:inherit;font-size:13px;color:var(--ink);background:var(--slot2);border:1px solid var(--line);border-radius:3px;padding:2px 4px}
.cledger .ctr{display:flex;align-items:center;gap:8px}
.cledger .ctr button{width:38px;padding:6px 0;font-size:17px;line-height:1;text-align:center;border-bottom-width:3px}
.cledger .ctr .n{flex:1;text-align:center;font-family:"JetBrains Mono",monospace;font-size:14px;color:var(--ink)}
.csum{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-bottom:14px;
position:relative;border:2px solid transparent;border-radius:8px;padding:8px}
.csum.allfull{border-color:#aab6c8;padding:14px;border-radius:12px;
background:
linear-gradient(112deg,rgba(255,255,255,0) 30%,rgba(255,255,255,.92) 44%,rgba(255,255,255,.35) 50%,rgba(255,255,255,0) 62%),
linear-gradient(168deg,#fbfdff 0%,#dbe3ee 16%,#aeb9ca 34%,#f4f8fc 48%,#9fabbe 62%,#e6ecf4 80%,#c2cdda 100%);
background-size:280% 100%,auto;
box-shadow:
inset 0 2px 0 rgba(255,255,255,.95),
inset 0 -3px 8px rgba(78,90,110,.45),
inset 0 0 0 1px rgba(255,255,255,.55),
0 6px 18px rgba(60,70,90,.3);
animation:mirrorSweep 4.2s ease-in-out infinite,allGlow 2.4s ease-in-out infinite}
@keyframes mirrorSweep{0%{background-position:-40% 0,0 0}100%{background-position:190% 0,0 0}}
.csum.allfull .u{box-shadow:0 3px 8px rgba(50,60,78,.3)}
.csum.allfull .u:not(.full){background:rgba(255,255,255,.88)}
.csum.allfull .u:not(.full) .t,.csum.allfull .u:not(.full) .s{color:#5a6475}
.csum.allfull .u:not(.full) .v{color:#232b38}
@keyframes allGlow{0%,100%{box-shadow:0 0 0 rgba(246,185,60,0)}50%{box-shadow:0 0 26px rgba(246,185,60,.45)}}
@media (prefers-reduced-motion:reduce){.csum.allfull{animation:none}}
@media(max-width:640px){.csum{grid-template-columns:repeat(3,1fr)}}
.csum .u{position:relative;overflow:hidden;background:var(--slot);border:1px solid var(--line);border-top:4px solid var(--c);border-radius:4px;padding:8px 10px}
.csum .u .t{font-size:12px;color:var(--ink2);margin-bottom:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.csum .u .v{font-family:"JetBrains Mono",monospace;font-size:13px;color:var(--ink)}
.csum .u .s{font-size:11px;color:var(--ink2);margin-top:4px}
.csum .u.full{border-color:var(--gold-d);border-top-color:var(--c);
background:linear-gradient(115deg,var(--gold-soft) 0%,color-mix(in srgb,var(--gold) 55%,var(--gold-soft)) 42%,var(--gold-soft) 72%);
background-size:240% 100%;
animation:sumSheen 2.8s linear infinite,sumGlow 1.9s ease-in-out infinite}
.csum .u.full .t,.csum .u.full .s{color:var(--gold-t)}
.csum .u.full .t{padding-right:76px}
