.fv-th{display:block;aspect-ratio:16/9;background:#141416;overflow:hidden}
.fv-th img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .3s}
.fv-c:hover .fv-th img,.fv-c:focus-visible .fv-th img{transform:scale(1.04)}
.fv-pill,.fv-age{position:absolute;z-index:2;display:inline-flex;align-items:center;border-radius:var(--rq-in,8px);color:#fff;
background:linear-gradient(180deg,rgba(28,28,32,.84),rgba(12,12,14,.74));border:1px solid rgba(255,255,255,.14);box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 2px 8px rgba(0,0,0,.35)}
.fv-pill{left:7px;top:7px;gap:5px;max-width:calc(100% - 52px);padding:2px 8px 2px 7px;font-size:11px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fv-pill i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--cc);box-shadow:0 0 6px var(--cc)}
.fv-age{right:7px;bottom:7px;padding:1px 7px;font:700 11px "JetBrains Mono",monospace}
.fv-c .fv-tw .vf-st{top:7px;right:7px;width:30px;height:28px;border-radius:var(--rq-in,8px);color:#fff;transform:none;backdrop-filter:none;-webkit-backdrop-filter:none;
background:linear-gradient(180deg,rgba(28,28,32,.84),rgba(12,12,14,.74));border:1px solid rgba(255,255,255,.14);box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 2px 8px rgba(0,0,0,.35)}
.fv-c .fv-tw .vf-st svg{width:15px;height:15px}
.fv-c .fv-tw .vf-st.on{color:var(--gold);background:linear-gradient(180deg,rgba(60,52,18,.88),rgba(30,26,8,.8));border-color:rgba(236,210,91,.55);box-shadow:inset 0 1px 0 rgba(255,255,255,.2),0 0 10px rgba(236,210,91,.25)}
.fv-c .fv-tw .vf-st.on svg{fill:currentColor;stroke:currentColor}
.fv-c .fv-tw .vf-st:hover{transform:scale(1.06)}
.fv-c.off{cursor:default;transform:none!important;background:rgba(255,255,255,.015)!important;border-style:dashed!important;border-color:rgba(255,255,255,.16)!important;box-shadow:none!important}
.fv-c.off .fv-th img{filter:grayscale(1) brightness(.55);transform:none!important}
.fv-c.off .fv-t,.fv-c.off .fv-dt,.fv-c.off .fv-m,.fv-c.off .fv-pill,.fv-c.off .fv-age{opacity:.38}
.fv-c.off .fv-m{pointer-events:none}
.fv-c.off .fv-tw .vf-st{color:var(--ink);border-color:rgba(255,255,255,.3);box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 0 0 3px rgba(236,210,91,.12)}
.fv-c.off .fv-tw .vf-st:hover{color:var(--gold);border-color:rgba(236,210,91,.55)}
.fv-t{padding:0 3px;min-height:2.7em;font-size:13.5px;font-weight:700;line-height:1.35;color:var(--ink);word-break:keep-all;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.fv-m{display:flex;flex-direction:column;gap:5px;margin-top:auto;padding:0 3px}
.fv-r{display:flex;align-items:baseline;justify-content:space-between;gap:8px;min-width:0;font-size:11.5px}
.fv-r > span{min-width:0;color:var(--ink3)}
.fv-r b{flex:0 0 auto;font:700 12px "JetBrains Mono",monospace;color:var(--ink);font-variant-numeric:tabular-nums}
.fv-g b{color:var(--sv)}
.fv-go b{font-family:inherit;font-size:11.5px;color:var(--sv)}
.fv-dt{min-width:0;margin-top:-5px;padding:0 3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font:600 11px "JetBrains Mono","Pretendard Variable",monospace;color:var(--ink3)}
.fv-ev{cursor:pointer}
.fv-cnt{align-self:flex-start;display:inline-flex;align-items:center;gap:5px;padding:4px 10px 4px 8px;border-radius:var(--rq-in,8px);font-size:11.5px;font-weight:700;color:var(--ink);
background:linear-gradient(180deg,rgba(110,184,255,.22),rgba(110,184,255,.07));border:1px solid rgba(130,196,255,.45);box-shadow:inset 0 1px 0 rgba(255,255,255,.16),0 0 10px rgba(110,184,255,.14)}
.fv-cnt svg{width:14px;height:14px;flex:0 0 auto;fill:none;stroke:#8cc8ff;stroke-width:1.8;stroke-linejoin:round}
.fv-cnt svg .pl{fill:#8cc8ff;stroke:none}
.fv-cnt b{font:800 12.5px "JetBrains Mono",monospace;color:#8cc8ff}
.fv-ana{margin-top:2px;cursor:pointer;transition:background .15s,border-color .15s,box-shadow .15s;
background:linear-gradient(180deg,rgba(255,77,79,.22),rgba(255,77,79,.08));border-color:rgba(255,110,110,.45);box-shadow:inset 0 1px 0 rgba(255,255,255,.16),0 0 10px rgba(255,77,79,.14)}
.fv-ana svg{fill:none;stroke:#ff8a8a;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.fv-ana .fv-anago{width:11px;height:11px;margin-left:-1px;opacity:.75;transition:transform .15s,opacity .15s}
.fv-ana:hover,.fv-ana:focus-visible{outline:none;background:linear-gradient(180deg,rgba(255,77,79,.34),rgba(255,77,79,.14));border-color:rgba(255,120,120,.75);box-shadow:inset 0 1px 0 rgba(255,255,255,.2),0 0 14px rgba(255,77,79,.3)}
.fv-ana:hover .fv-anago{transform:translateX(2px);opacity:1}
@media (max-width:560px){
.fv-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 10px}
.fv-pill{font-size:10px;padding:2px 7px 2px 6px}
.fv-sorts{flex:1 1 100%;flex-wrap:nowrap;justify-content:space-between;gap:6px}
.fv-sort button{padding:5px 8px}
.fv-t{font-size:12.5px}
.fv-cnt{padding:3px 8px 3px 7px;font-size:11px}
.fv-r{flex-wrap:wrap;column-gap:6px;row-gap:1px}
}